# -*- coding: utf-8 -*-
"""Нижний блок части 1 «Подготовка информации для работы с ИИ»: ДЗ пары 1 и относящиеся к ней промпты."""
from lib import card, table, steps, paras, slide, sec
from prompts import PROMPTS

GROUP_ORDER_1 = ["Подготовка данных", "Шаблоны документов", "Роль в промпте"]


def s13a() -> str:
    b = slide(23, "Слайд «Итог части 1 и домашнее задание»: формула пары 1, три пункта домашнего задания, «Подготовил — значит проверил, что уходит»",
              ["Слайд собирает первую часть урока в одну картинку: слева — формула пары 1 (задача, необходимые данные, минимизация, обезличивание, проверка настроек, передача в ИИ), справа — домашнее задание. Сфотографируйте его: это ваша шпаргалка на ближайшие недели.",
               "Часть 2 «Правовые и репутационные риски применения ИИ» отвечает на вопрос «что делать с результатом, который вернул ИИ?» — это отдельная страница и отдельное занятие."],
              takeaway="Прежде чем передать что-то ИИ, пройдите шесть шагов паспорта задачи.")
    b += card("Домашнее задание (до следующего занятия)",
              steps(["<b>Паспорт безопасной задачи</b> для двух типов ваших рабочих задач (например, «письмо контрагенту» и «справка руководителю»). Реальных данных не пишите: только тип информации, что нужно ИИ, что убрать, что заменить, где обрабатывать, кто проверит, что вы не знаете и у кого уточните. Бланк — в файлах ниже.",
                     "<b>Личный чек-лист</b> выше на странице: пройдите его перед следующей отправкой запроса в ИИ.",
                     "<b>Один файл</b> без реальных данных: две строки паспорта задачи."])
              + '<p class="q-hint">Критерии: (1) в паспорте нет реальных данных; (2) указано, кто проверяет результат; (3) неизвестное записано как вопрос, а не как разрешение.</p>')
    b += card("Как пользоваться шаблонами промптов",
              paras(["Все шаблоны построены одинаково: <b>задача</b>, <b>для кого</b>, <b>что известно</b>, <b>что сделать</b>, <b>формат</b>, <b>границы</b>. Всё, что зависит от фактов, стоит в квадратных скобках — заполняете вы, не модель. Роль, если указана, задаёт позицию, формат и тон; проверка фактов остаётся за вами.",
                     "Перед использованием: 1) прочитайте описание промпта; 2) замените поля в скобках условными данными; 3) отправьте в разрешённый инструмент; 4) проверьте результат. Для показа на занятии один и тот же промпт отправляйте по очереди в GigaChat, DeepSeek и ChatGPT в новых чатах."]))
    items = [p for p in PROMPTS if p["group"] in GROUP_ORDER_1]
    rows = [[p["id"], p["title"], p["group"]] for p in items]
    b += table(f"Каталог: {len(items)} промптов части 1", ["№", "Название", "Группа"], rows)
    b += f'<div class="deep-bar fade"><span>⌨️ Все {len(items)} промптов части 1</span><b>Копируются целиком одной кнопкой</b></div>'
    for g in GROUP_ORDER_1:
        gitems = [p for p in PROMPTS if p["group"] == g]
        if not gitems:
            continue
        b += f'<h3 class="fade" style="margin:22px 0 8px;font-size:1.05rem">{g}</h3><div class="pk-grid">' + "".join(f"{{{{PK:{p['id']}}}}}" for p in gitems) + "</div>"
    b += '<p class="q-hint fade">Промпты проверки результата и вопросов ответственному — на странице части 2 «Правовые и репутационные риски». Все данные в промптах условные.</p>'
    b += """<div class="dl-grid fade" style="margin-top:20px">
    <a class="dl" href="../data/urok4/prompty_urok4.docx" download><span class="ico">📝</span><div><b>Промпты урока · DOCX</b><span>Все 21 промпт урока 4 + 8 промптов практикума</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/prompty_urok4.xlsx" download><span class="ico">📊</span><div><b>Промпты урока · XLSX</b><span>Таблица с группами и описаниями, для менеджера промптов</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/pasport_bezopasnoy_zadachi.docx" download><span class="ico">📋</span><div><b>Паспорт безопасной задачи</b><span>DOCX · бланк и заполненный образец</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/domashnee_zadanie_blank.docx" download><span class="ico">🏠</span><div><b>Домашнее задание · бланк DOCX</b><span>Паспорт задачи и другие разделы</span></div><span class="arrow">↓</span></a>
  </div>"""
    return sec("s13", "13", "Домашнее задание и шаблоны промптов части 1",
               "Что сделать после части 1 и промпты для повседневных документов и безопасной подготовки данных. Всё можно скачать.", b, "после занятия")
